// Independent instantaneous rocket and constant-acceleration/coast equations.
// No GMAT force,frame,integrator or mass-conversion implementation is called.
static QJsonArray oracle(const QString &mode)
{
 const bool impulse=mode=="Impulse";QJsonArray rows;double mass=1000,t=0,x=7000,vx=0,vy=1,vz=0;
 for(int i=1;i<=3;++i){
  if(impulse){const double a=.001*i,b=-.002*i,c=.0005*i,isp=250+50*i;
   for(int phase=0;phase<2;++phase){if(phase){vx+=a;vy+=b;vz+=c;mass*=std::exp(-1000*std::sqrt(a*a+b*b+c*c)/(isp*10));}
    rows.append(QJsonArray{i,phase,0,7000,0,0,vx,vy,vz,mass-900,mass,a,b,c,isp,41});}
  }else{
   const double duty=mode=="Duty"?i/4.:.5,scale=mode=="Scale"?i-1:1,force=100*duty*scale,acceleration=force/1000000;
   auto row=[&](int phase,bool firing){const double f=firing?force:0;return QJsonArray{i,phase,t,x,t,0,vx,1,0,100,1000,duty,scale,f,f,0,0,f/1000000,0,0,0,41};};
   rows.append(row(0,false));rows.append(row(1,true));x+=vx*10+.5*acceleration*100;vx+=acceleration*10;t+=10;rows.append(row(2,true));rows.append(row(3,false));x+=vx*10;t+=10;rows.append(row(4,false));
  }
 }
 return rows;
}
static double tolerance(int column){return column==2?2e-6:column>=3&&column<=5?1e-7:column>=6&&column<=8?1e-10:column==9||column==10?1e-8:1e-9;}
static void compare(const QJsonArray &got,const QJsonArray &want)
{
 require(got.size()==want.size(),"Burn-loop state width differs");
 for(int i=0;i<got.size();++i){const double a=got[i].toDouble(),b=want[i].toDouble();if(!std::isfinite(a)||std::abs(a-b)>tolerance(i))std::cerr<<"BURN_LOOP_DIFF column="<<i<<" actual="<<a<<" expected="<<b<<std::endl;require(std::isfinite(a)&&std::abs(a-b)<=tolerance(i),"Burn-loop state differs from independent impulse/constant-force oracle");}
}
static void reveal(QWidget *w)
{
 require(w,"Burn-loop control absent");for(QWidget *p=w;p;p=p->parentWidget())if(auto *s=qobject_cast<QScrollArea *>(p))s->ensureWidgetVisible(w);events();require(w->isVisible()&&w->isEnabled(),"Burn-loop control unreachable");
}
